            self.check_name(node, arg.arg)
        if node.args.vararg:
            self.check_name(node, node.args.vararg.arg)
        if node.args.kwarg:
            self.check_name(node, node.args.kwarg.arg)
        for arg in node.args.kwonlyargs:
