def register_views(app: Flask) -> None:
    @app.after_request
    def add_header(r: Response) -> Response:
        """
        Disable cache for all auth server requests
        """
        r.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
        r.headers["Pragma"] = "no-cache"
