        self.pp.msg = "a{} {}".format(self.pp.n, cdir)
        rd = cdir[len(top) :].strip("/")
        if WINDOWS:
            rd = rd.replace("\\", "/").strip("/")
        g = statdir(self.log_func, not self.args.no_scandir, False, cdir)
        gl = sorted(g)
        partials = set([x[0] for x in gl if "PARTIAL" in x[0]])
        for iname, inf in gl:
            if self.stop:
                return -1
            rp = vjoin(rd, iname)
            abspath = os.path.join(cdir, iname)
