        tmpl, tmpl_dict = self._downloader.prepare_outtmpl(cmd, info)
        if tmpl_dict:
            return self._downloader.escape_outtmpl(tmpl) % tmpl_dict
        filepath = info.get('filepath', info.get('_filename'))
        if filepath:
            if '{}' not in cmd:
                cmd += ' {}'
            cmd = cmd.replace('{}', compat_shlex_quote(filepath))
